function s(v){return String(v==null?'':v).trim();}
function colL(i){let n=i+1,t='';while(n>0){const m=(n-1)%26;t=String.fromCharCode(65+m)+t;n=Math.floor((n-1)/26);}return t;}
const body=$('Webhook').first().json.body||{};
if(body.secret!=='sv-crit-2026-09-17-q8Lz'){throw new Error('bad secret');}
const dry=body.dry!==false;const patches=body.patches||[];
if(!Array.isArray(patches)||patches.length>150){throw new Error('bad patch list');}
const rows=$('GET criteria').first().json.values||[];if(rows.length<200){throw new Error('ABORT short criteria read '+rows.length);}
const h=rows[0].map(s);const X={};h.forEach((k,i)=>X[k]=i);
const CODES=new Set('D2C_BEAUTY_PERSONAL_CARE,D2C_HEALTH_WELLNESS,D2C_FASHION_JEWELLERY,D2C_HOME_LIFESTYLE,FNB_PACKAGED_FOOD,FNB_BEVERAGE,ALCOHOL,FNB_FOODSERVICE,MEAT_SEAFOOD,CONSUMER_TECH_APP,CONSUMER_SERVICES,QUICK_HYPERLOCAL_COMMERCE,RETAIL_TECH,TRAVEL_HOSPITALITY,PET,MEDIA_GAMING_CREATOR,AI_FOUNDATIONAL,AI_APPLIED_ENTERPRISE,SAAS_ENTERPRISE,MARTECH_ADTECH,HRTECH,CYBERSECURITY,DATA_INFRA_DEVTOOLS,IOT_SMART_HARDWARE,SEMICONDUCTOR_ELECTRONICS,SPACETECH,DEFENCE_AEROSPACE,XR_IMMERSIVE,FINTECH_CONSUMER,FINTECH_SME_LENDING,FINTECH_INFRA,INSURTECH,HEALTHTECH_DIGITAL,HEALTHCARE_DELIVERY,MEDTECH_DEVICES,BIOTECH_PHARMA,EDTECH_K12_TESTPREP,EDTECH_HIGHER_ED_ADMISSIONS,EDTECH_UPSKILLING_ENTERPRISE,CLIMATE_ENERGY,EV_CLEAN_MOBILITY,WATER_TECH,AGRITECH,SUSTAINABLE_MATERIALS_CIRCULAR,LOGISTICS_SUPPLY_CHAIN,MANUFACTURING_INDUSTRIAL,CONSTRUCTION_INFRA_TECH,REAL_ESTATE_COWORKING_PROPTECH,LEGAL_GOV_TECH,SAFETY_FIRE_TECH,D2C_BRAND,B2C_APP_PLATFORM,B2C_MARKETPLACE,B2B_SAAS,B2B_MARKETPLACE,B2B_SERVICES_OPERATOR,B2B2C,HARDWARE_DEVICE,INFRA_API_PLATFORM,DEEP_IP_RND,ANY'.split(','));
const STAGES=['PRE_SEED','SEED','TRACTION','PRE_SERIES_A','SERIES_A','SERIES_B','SERIES_C_PLUS'];
const LISTF=['sectors_in','sectors_excluded','models_in','models_excluded'];const UNION=['sectors_excluded','models_excluded'];
const ALLOWED=['sector_mode','sectors_in','sectors_excluded','models_in','models_excluded','stage_min','stage_max','cheque_min_cr','cheque_max_cr','lead_max_cr','round_max_cr','arr_min_cr','revenue_required','geography_scope','status'];
const splitL=v=>s(v).split(/[,;|]/).map(x=>x.trim()).filter(Boolean);
const data=[];const report=[];const errors=[];
for(const p of patches){const sr=s(p.sheet_row);let ri=-1;for(let i=1;i<rows.length;i++){if(s((rows[i]||[])[X.sheet_row])===sr){ri=i;break;}}
  if(ri<0){errors.push(sr+' '+p.firm+': sheet_row not found');continue;}
  const row=rows[ri]||[];const rn=ri+1;const done=[];
  for(const [f,v0] of Object.entries(p.changes||{})){
    if(ALLOWED.indexOf(f)<0||X[f]===undefined){errors.push(sr+' '+f+': field not allowed');continue;}
    let v=v0;
    if(LISTF.indexOf(f)>=0){let items=splitL(v);const bad=items.filter(c=>!CODES.has(c));if(bad.length){errors.push(sr+' '+f+' dropped unknown '+bad.join('/'));}items=items.filter(c=>CODES.has(c));
      if(UNION.indexOf(f)>=0){const cur=splitL(row[X[f]]);items=cur.concat(items.filter(c=>cur.indexOf(c)<0));}
      v=items.join(', ');}
    if((f==='stage_min'||f==='stage_max')&&STAGES.indexOf(s(v))<0){errors.push(sr+' '+f+' bad stage '+v);continue;}
    if(f==='status'&&['ACTIVE','HOLD','STOP','DNC'].indexOf(s(v))<0){errors.push(sr+' bad status');continue;}
    if(f==='sector_mode'&&['AGNOSTIC','LIST'].indexOf(s(v))<0){errors.push(sr+' bad sector_mode');continue;}
    if((f==='cheque_min_cr'||f==='cheque_max_cr'||f==='lead_max_cr'||f==='round_max_cr'||f==='arr_min_cr')&&s(v)!==''&&!isFinite(Number(v))){errors.push(sr+' '+f+' not a number');continue;}
    // A ceiling is enforced by ENGINE-DAILY and fails OPEN when blank: only 1 of 303
    // investors has one on file, so a wrong value mutes real matches while a missing
    // one costs nothing. Refuse a negative or absurd figure rather than write it.
    if((f==='cheque_max_cr'||f==='lead_max_cr'||f==='round_max_cr')&&s(v)!==''&&(Number(v)<=0||Number(v)>10000)){errors.push(sr+' '+f+' out of range '+v);continue;}
    if(f==='revenue_required'){v=/^y/i.test(s(v))?'Y':'N';}
    const before=s(row[X[f]]);if(before===s(v)){continue;}
    data.push({range:'INVESTOR_CRITERIA!'+colL(X[f])+rn,values:[[String(v)]]});done.push(f+': '+before.slice(0,60)+' -> '+String(v).slice(0,80));}
  if(done.length){const notes=s(row[X.rule_notes]);data.push({range:'INVESTOR_CRITERIA!'+colL(X.rule_notes)+rn,values:[[(notes?notes+' | ':'')+s(p.note).slice(0,300)]]});report.push(sr+' '+s(row[X.investor])+' :: '+done.join(' ; '));}
}
return [{json:{dry:dry,cells:data.length,rows_changed:report.length,errors:errors,report:report,data:dry?[]:data}}];
